import{_ as e,c as a,o as t,a4 as s}from"./chunks/framework.4aTu-Nia.js";const x=JSON.parse('{"title":"Next.js","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/next.md","filePath":"frameworks/next.md"}'),l={name:"frameworks/next.md"},r=s(`<h1 id="next-js" tabindex="-1">Next.js <a class="header-anchor" href="#next-js" aria-label="Permalink to &quot;Next.js&quot;">​</a></h1><p><code>Next.js</code> 是一个 React 应用程序的服务端渲染框架、全栈框架</p><p>集成 css module</p><p>服务商级别的优化和便利</p><h2 id="特点" tabindex="-1">特点 <a class="header-anchor" href="#特点" aria-label="Permalink to &quot;特点&quot;">​</a></h2><p>现代化框架需要哪些特性</p><ol><li>自动代码分割（跟 vue/react 脚手架类似，基于页面）：Next.js 会自动将页面和组件按需加载，提高页面加载速度和性能。</li><li>服务器端渲染（vs 客户端渲染）：Next.js 支持服务器端渲染，可以提高 SEO 和首屏加载速度。</li><li>静态文件服务（没区别）：Next.js 可以将静态文件直接服务于客户端，提高页面加载速度。</li><li>自动优化（vs 手动）：Next.js 会自动分析页面和组件，进行优化，提高性能。</li><li>热加载（有变化？）：Next.js 支持热加载，修改代码后可以快速看到效果。</li><li>客户端路由：Next.js 支持客户端路由，可以提高用户体验。</li><li>支持 TypeScript：Next.js 支持 TypeScript，提供了更好的类型检查和 IDE 支持。</li><li>支持 API 路由（全栈）：Next.js 可以直接将 API 服务于客户端，方便构建前后端分离应用。</li><li>支持多种部署方式：Next.js 可以部署在多种环境中，包括服务器、静态托管服务和云函数等。</li></ol><h2 id="hello-world" tabindex="-1">hello world <a class="header-anchor" href="#hello-world" aria-label="Permalink to &quot;hello world&quot;">​</a></h2><p>pages -&gt; next -&gt; next build -&gt; next start(prod)</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>mkdir hello-next</span></span>
<span class="line"><span>cd hello-next</span></span>
<span class="line"><span>npm init -y</span></span>
<span class="line"><span>npm install --save react react-dom next</span></span>
<span class="line"><span>mkdir pages</span></span>
<span class="line"><span></span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  &quot;scripts&quot;: {</span></span>
<span class="line"><span>    &quot;dev&quot;: &quot;next&quot;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>import Link from &#39;next/link&#39;</span></span></code></pre></div><p>pages 目录最关键，不可变</p><h2 id="与-nest-js-区别" tabindex="-1">与 Nest.js 区别 <a class="header-anchor" href="#与-nest-js-区别" aria-label="Permalink to &quot;与 Nest.js 区别&quot;">​</a></h2><p><code>Nest.js</code> 是一个基于 Node.js 平台的开发框架，类似 eggjs</p><h2 id="fast-refresh" tabindex="-1">fast refresh <a class="header-anchor" href="#fast-refresh" aria-label="Permalink to &quot;fast refresh&quot;">​</a></h2><p>与 HMR 类似？</p><h2 id="编译" tabindex="-1">编译 <a class="header-anchor" href="#编译" aria-label="Permalink to &quot;编译&quot;">​</a></h2><p>5000个模块，intel 编译 5-10s，m1 2-4s，快一倍</p><p>React 服务器组件也是如此。人们听到“服务器”并假设是 Node.js。但 RSC 可以在构建期间运行。事实上，在 Next 13 App Router 中它是<em>默认值</em>。如果你在 RSC 中获取某些东西，它将<em>在构建时</em>，除非你选择动态渲染。</p><p>我们看到的转变（是的，正在努力实现）并不是从“编写 SPA”到“不编写 SPA”。它是从“被锁定在 SPA 中”（以后很难添加内置时间或服务器端集成）到“使用对每个页面有意义的任何模式”。hybrid era.</p><p>这是一种转变，但主要是一种心理转变。</p><p><a href="https://gist.github.com/gaearon/9d6b8eddc7f5e647a054d7b333434ef6" target="_blank" rel="noreferrer">Next.js SPA example with dynamic client-only routing and static hosting</a></p><p><a href="https://julesblom.com/writing/map-of-react-api" target="_blank" rel="noreferrer">Map of React API - JulesBlom.com</a></p><h2 id="原理" tabindex="-1">原理 <a class="header-anchor" href="#原理" aria-label="Permalink to &quot;原理&quot;">​</a></h2><ol><li>将 pages 的文件编译</li><li>编译时根据文件结构顺便把路由配置表生成</li><li>请求时根据请求路径去路由表查询结果，最后根据路由动态加载相应的页面文件。</li></ol><h2 id="自动优化" tabindex="-1">自动优化 <a class="header-anchor" href="#自动优化" aria-label="Permalink to &quot;自动优化&quot;">​</a></h2><ol><li>自动代码分割：Next.js 会自动将页面和组件按需加载，提高页面加载速度和性能。</li><li>预取：Next.js 会自动分析页面和组件的依赖关系，提前加载可能需要的资源，从而减少页面加载时间。</li><li>缓存：Next.js 会自动缓存静态资源和页面数据，提高页面加载速度和性能。</li><li>压缩和混淆：Next.js 会自动压缩和混淆 JavaScript 和 CSS 代码，减少文件大小，提高页面加载速度和性能。</li><li>图像优化：Next.js 会自动优化图像，包括压缩、缩放和 WebP 转换等，提高页面加载速度和性能。</li><li>预渲染：Next.js 支持预渲染，可以将页面预先生成为静态 HTML 文件，提高 SEO 和首屏加载速度。</li></ol><h2 id="image-组件" tabindex="-1">Image 组件 <a class="header-anchor" href="#image-组件" aria-label="Permalink to &quot;Image 组件&quot;">​</a></h2><p>性能：最优格式和体积 体验：占位</p><p>内转 proxy server，可处理远程图片</p><p>后缀名与 MIME 可能不一致</p><h2 id="打包部署" tabindex="-1">打包部署 <a class="header-anchor" href="#打包部署" aria-label="Permalink to &quot;打包部署&quot;">​</a></h2><p>默认输出到 .next 文件夹</p><h3 id="自托管" tabindex="-1">自托管 <a class="header-anchor" href="#自托管" aria-label="Permalink to &quot;自托管&quot;">​</a></h3><p>自己搭个 node 环境，体验落后且维护成本高</p><p>导出纯静态托管 <a href="https://nextjs.org/docs/advanced-features/static-html-export" target="_blank" rel="noreferrer">Advanced Features: Static HTML Export | Next.js</a></p><h3 id="vercel-部署优化" tabindex="-1">vercel 部署优化 <a class="header-anchor" href="#vercel-部署优化" aria-label="Permalink to &quot;vercel 部署优化&quot;">​</a></h3><p>api 路由走 serverless function，无限扩容 Middleware 走 edge function，快速启动</p><p>git 钩子自动部署</p><ol><li>什么是 Next.js 的服务器端渲染（SSR）？有什么优点和缺点？ <ul><li>优点：首屏、SEO</li><li>缺点：开发、部署成本，服务器压力</li></ul></li><li>如何在 Next.js 中使用数据获取（Data Fetching）？有哪些方式可以实现数据获取？</li><li>什么是 Next.js 的静态生成（Static Generation）？与服务器端渲染有何不同？</li><li>如何在 Next.js 中实现动态路由（Dynamic Routing）？有哪些注意点？</li><li>如何在 Next.js 中实现代码分割（Code Splitting）？有哪些常见的代码分割策略？</li></ol><h3 id="部署到-cloudflare" tabindex="-1">部署到 cloudflare <a class="header-anchor" href="#部署到-cloudflare" aria-label="Permalink to &quot;部署到 cloudflare&quot;">​</a></h3><p><a href="https://github.com/cloudflare/next-on-pages" target="_blank" rel="noreferrer">https://github.com/cloudflare/next-on-pages</a> 基于已有项目执行</p><h3 id="多服务器" tabindex="-1">多服务器 <a class="header-anchor" href="#多服务器" aria-label="Permalink to &quot;多服务器&quot;">​</a></h3><p>build id 是随机的，多个不同的构建会导致缓存失效。解决方案是定制 buid id 方法，比如使用 git commit id</p><p><a href="https://levelup.gitconnected.com/how-to-deploy-next-js-on-multiple-servers-3b493d4ce0e9" target="_blank" rel="noreferrer">How To Deploy Next.js on Multiple Servers | Level Up Coding</a></p><h2 id="数据获取" tabindex="-1">数据获取 <a class="header-anchor" href="#数据获取" aria-label="Permalink to &quot;数据获取&quot;">​</a></h2><p>getStaticProps 构建时预渲染，不怎么变的数据。框架勾子，拿到的数据，以 prop 传递给组件 getServerSideProps 实时更新 getStaticPaths</p><blockquote><p>在构建时，Next.js将使用getStaticPaths返回的参数值来生成静态页面。对于每个参数值，Next.js将调用getStaticProps函数，获取该参数的静态数据，并将其传递给页面组件作为props。</p></blockquote><p><img src="https://mmbiz.qpic.cn/mmbiz_png/ZCdKIQujeZya9N0I4XCYSNLb8bVXoCicArsOTUhGto6QmADytvuZL2R0y7Wpbd4EHH2GblTVVWxWuHkZoibPljrQ/640?wx_fmt=png&amp;wxfrom=5&amp;wx_lazy=1&amp;wx_co=1" alt="640 (1080×538)"></p><h2 id="国内" tabindex="-1">国内 <a class="header-anchor" href="#国内" aria-label="Permalink to &quot;国内&quot;">​</a></h2><p>umi</p><p>如果是今年选Node.js Web框架，大概只有Midway、Nest和next.js了</p><h2 id="缺点" tabindex="-1">缺点 <a class="header-anchor" href="#缺点" aria-label="Permalink to &quot;缺点&quot;">​</a></h2><p>不适合深度定制 适合大厂吗？</p><p><a href="https://mp.weixin.qq.com/s/5Ir7EoHLo37bs6W5WNa-Tw" target="_blank" rel="noreferrer">我看Next.js：一个更现代的海王</a></p><pre><code>Next.js 的事情相当复杂。开发服务器做了太多事情。复杂度转移，开发简单，部署迁移复杂。
</code></pre><p>可迁移性不确定、支持度不确定。平台捆绑。</p><p><a href="https://zhuhaow.me/want-nextjs-at-edge-just-use-vercel/" target="_blank" rel="noreferrer">Want Next.js at the edge? Just use Vercel | Not a blog</a></p><p><a href="https://www.v2ex.com/t/938396" target="_blank" rel="noreferrer">https://www.v2ex.com/t/938396</a></p><h2 id="prisma" tabindex="-1">prisma <a class="header-anchor" href="#prisma" aria-label="Permalink to &quot;prisma&quot;">​</a></h2><p>[[prisma]]</p>`,60),n=[r];function i(o,p,h,c,d,u){return t(),a("div",null,n)}const b=e(l,[["render",i]]);export{x as __pageData,b as default};
